mapper.select:
SELECT an.ID AS ID, and1.id as detailId, an.code AS code, and1.asset_id AS assetId, and1.asset_code AS assetCode, and1.asset_name AS assetName, pp.main_supplier AS supplierId, and1.plan_deliver_date AS planDeliverDate, and1.apply_qty AS applyQty, COALESCE((and1.apply_qty - COALESCE(SUM(apod.purchase_qty),0)), 0) AS waitQty, COALESCE(SUM(apod.purchase_qty),0) AS realPurchaseQty, an.approve_user_id AS approveUserId, an.approve_user_name AS approveUserName, an.approve_time AS approveTime, an.apply_user_id AS applyUserId, an.apply_user_name as applyUserName, an.create_user_id AS createUserId, an.create_user_name AS createUserName, an.create_time AS createTime, an.approve_status as approveStatus, an.invalid_status as invalidStatus, and1.create_po_type as createPoType FROM asset_notice an LEFT JOIN asset_notice_detail and1 ON an.id = and1.main_id and and1.is_deleted = false LEFT JOIN product_detail pd on pd.sku_no = and1.asset_code LEFT JOIN product_info pi on pi.id = pd.product_id LEFT JOIN product_purchase pp on pp.sku_id = pi.id LEFT JOIN asset_purchase_order_detail apod ON apod.source_detail_id = and1.id AND apod.is_deleted = false LEFT JOIN asset_purchase_order apo ON apo.id = apod.main_id AND apo.approve_status = 'approve' and apo.is_deleted = false WHERE ${params.sqlMap.default} and an.is_deleted = false
${params.permissionSql}
GROUP BY
${item.field} ${item.sort}
an.ID, an.code, and1.asset_id, and1.asset_code, and1.asset_name, pp.main_supplier, and1.plan_deliver_date, and1.apply_qty, and1.create_po_type, and1.id order by an.create_time desc

SELECT approve_status AS tabFlag, count(*) AS count FROM asset_notice WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
